using DadoRetail.Domain.Auditing;using DadoRetail.Domain.Fiscalization;using DadoRetail.Domain.Identity;using DadoRetail.Domain.Inventory;using DadoRetail.Domain.Organization;using DadoRetail.Domain.Partners;using DadoRetail.Domain.Payments;using DadoRetail.Domain.Pricing;using DadoRetail.Domain.Products;using DadoRetail.Domain.Purchasing;using DadoRetail.Domain.Sales;using Microsoft.EntityFrameworkCore;namespace DadoRetail.Infrastructure.Persistence;public sealed class DadoRetailDbContext(DbContextOptions<DadoRetailDbContext> options):DbContext(options){public DbSet<Product> Products=>Set<Product>();public DbSet<Barcode> Barcodes=>Set<Barcode>();public DbSet<User> Users=>Set<User>();public DbSet<Role> Roles=>Set<Role>();public DbSet<Permission> Permissions=>Set<Permission>();public DbSet<Store> Stores=>Set<Store>();public DbSet<Warehouse> Warehouses=>Set<Warehouse>();public DbSet<CashRegister> CashRegisters=>Set<CashRegister>();public DbSet<Supplier> Suppliers=>Set<Supplier>();public DbSet<StockBalance> StockBalances=>Set<StockBalance>();public DbSet<StockMovement> StockMovements=>Set<StockMovement>();public DbSet<InventoryDocument> Inventories=>Set<InventoryDocument>();public DbSet<InventoryLine> InventoryLines=>Set<InventoryLine>();public DbSet<Purchase> Purchases=>Set<Purchase>();public DbSet<PurchaseItem> PurchaseItems=>Set<PurchaseItem>();public DbSet<Sale> Sales=>Set<Sale>();public DbSet<SaleItem> SaleItems=>Set<SaleItem>();public DbSet<Payment> Payments=>Set<Payment>();public DbSet<FiscalTransaction> FiscalTransactions=>Set<FiscalTransaction>();public DbSet<AuditLog> AuditLogs=>Set<AuditLog>();public DbSet<Price> Prices=>Set<Price>();public DbSet<Promotion> Promotions=>Set<Promotion>();protected override void OnModelCreating(ModelBuilder m){m.Entity<Product>(b=>{b.ToTable("products");b.HasKey(x=>x.Id);b.HasIndex(x=>x.Sku).IsUnique();b.HasMany(x=>x.Barcodes).WithOne(x=>x.Product).HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Cascade);});m.Entity<Barcode>(b=>{b.ToTable("barcodes");b.HasKey(x=>x.Id);b.HasIndex(x=>x.Value).IsUnique();});m.Entity<User>(b=>{b.ToTable("users");b.HasKey(x=>x.Id);b.HasIndex(x=>x.Username).IsUnique();});m.Entity<Role>(b=>{b.ToTable("roles");b.HasKey(x=>x.Id);b.HasIndex(x=>x.Name).IsUnique();});m.Entity<Permission>(b=>{b.ToTable("permissions");b.HasKey(x=>x.Id);b.HasIndex(x=>x.Code).IsUnique();});m.Entity<UserRole>(b=>{b.ToTable("user_roles");b.HasKey(x=>new{x.UserId,x.RoleId});b.HasOne(x=>x.User).WithMany(x=>x.Roles).HasForeignKey(x=>x.UserId);b.HasOne(x=>x.Role).WithMany(x=>x.Users).HasForeignKey(x=>x.RoleId);});m.Entity<RolePermission>(b=>{b.ToTable("role_permissions");b.HasKey(x=>new{x.RoleId,x.PermissionId});b.HasOne(x=>x.Role).WithMany(x=>x.Permissions).HasForeignKey(x=>x.RoleId);b.HasOne(x=>x.Permission).WithMany(x=>x.Roles).HasForeignKey(x=>x.PermissionId);});m.Entity<Store>(b=>{b.ToTable("stores");b.HasKey(x=>x.Id);b.HasIndex(x=>x.Code).IsUnique();});m.Entity<Warehouse>(b=>{b.ToTable("warehouses");b.HasKey(x=>x.Id);b.HasIndex(x=>new{x.StoreId,x.Code}).IsUnique();});m.Entity<CashRegister>(b=>{b.ToTable("cash_registers");b.HasKey(x=>x.Id);b.HasIndex(x=>new{x.StoreId,x.Code}).IsUnique();});m.Entity<Supplier>(b=>{b.ToTable("suppliers");b.HasKey(x=>x.Id);b.HasIndex(x=>x.Name);});m.Entity<StockBalance>(b=>{b.ToTable("stock_balances");b.HasKey(x=>x.Id);b.Property(x=>x.Quantity).HasPrecision(18,3);b.HasIndex(x=>new{x.WarehouseId,x.ProductId}).IsUnique();});m.Entity<StockMovement>(b=>{b.ToTable("stock_movements");b.HasKey(x=>x.Id);b.Property(x=>x.Quantity).HasPrecision(18,3);b.HasIndex(x=>x.DocumentId);});m.Entity<InventoryDocument>(b=>{b.ToTable("inventories");b.HasKey(x=>x.Id);b.HasMany(x=>x.Lines).WithOne().HasForeignKey(x=>x.InventoryId);});m.Entity<InventoryLine>(b=>{b.ToTable("inventory_lines");b.HasKey(x=>x.Id);b.Property(x=>x.BookQuantity).HasPrecision(18,3);b.Property(x=>x.ActualQuantity).HasPrecision(18,3);b.Ignore(x=>x.Difference);});m.Entity<Purchase>(b=>{b.ToTable("purchases");b.HasKey(x=>x.Id);b.HasMany(x=>x.Items).WithOne().HasForeignKey(x=>x.PurchaseId);});m.Entity<PurchaseItem>(b=>{b.ToTable("purchase_items");b.HasKey(x=>x.Id);b.Property(x=>x.Quantity).HasPrecision(18,3);b.Property(x=>x.PurchasePrice).HasPrecision(18,2);});m.Entity<Sale>(b=>{b.ToTable("sales");b.HasKey(x=>x.Id);b.HasMany(x=>x.Items).WithOne().HasForeignKey(x=>x.SaleId);b.Ignore(x=>x.Total);});m.Entity<SaleItem>(b=>{b.ToTable("sale_items");b.HasKey(x=>x.Id);b.Property(x=>x.Quantity).HasPrecision(18,3);b.Property(x=>x.UnitPrice).HasPrecision(18,2);b.Property(x=>x.DiscountAmount).HasPrecision(18,2);});m.Entity<Payment>(b=>{b.ToTable("payments");b.HasKey(x=>x.Id);b.Property(x=>x.Amount).HasPrecision(18,2);b.HasIndex(x=>x.ProviderTransactionId);});m.Entity<FiscalTransaction>(b=>{b.ToTable("fiscal_transactions");b.HasKey(x=>x.Id);b.HasIndex(x=>x.SaleId);});m.Entity<AuditLog>(b=>{b.ToTable("audit_logs");b.HasKey(x=>x.Id);b.HasIndex(x=>x.CorrelationId);});m.Entity<Price>(b=>{b.ToTable("prices");b.HasKey(x=>x.Id);b.Property(x=>x.Amount).HasPrecision(18,2);});m.Entity<Promotion>(b=>{b.ToTable("promotions");b.HasKey(x=>x.Id);b.Property(x=>x.DiscountPercent).HasPrecision(5,2);});}}
